svg.script:
// The portal is bundled, not fetched from another private website.
// A same-origin HTML Blob preserves HTML parsing, scripts, hash navigation,
// fullscreen and browser storage. This SVG must be opened as a document,
// not as an <img>, because image contexts disable interactive scripting.
(function(){
  var payload="";
  var bytes=Uint8Array.from(atob(payload),function(c){return c.charCodeAt(0);});
  var url=URL.createObjectURL(new Blob([bytes],{type:'text/html;charset=utf-8'}));
  document.getElementById('cozes-app').src=url;
  window.addEventListener('pagehide',function(){URL.revokeObjectURL(url);},{once:true});
})();
